window.products.push({"id":522939,"name":"Bron Coucke 10201 Chef Mandoline Polycarbonate Hand Guard","category":"homeandappliances","retail price":36.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61RI50e0GjL._AC_SL1000_.jpg","description":"Use this Bron Coucke 10201 mandoline guard to replace the guard that came with your Bron Coucke 15000 or 21038 mandoline, or to accompany your 3839 mandoline. Made out of black polycarbonate, this guard is sturdy and durable. It keeps your fingers safely out of the way while you're using your mandoline. Whether you're slicing onions, potatoes, or lemons and limes, you can go about your kitchen duties without any fear of getting cut or nicked!","images":["https://m.media-amazon.com/images/I/61RI50e0GjL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bron Coucke","source_asin":"B00CPAW1GE","category_path":"Home & Kitchen"},"sku":"BM-522939","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00CPAW1GE","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00CPAW1GE","price_pending":true,"merchant_ready":false});
